// 02.11.2026: прошедшее, слишком близкое или не указанное время не мешает публикации —
// перед самым сохранением оно сдвигается на ближайшее допустимое (через 2 минуты).
let shiftedSoon=false;

function approvalProblems(schedule=true){const issues=[];if(post.readiness?.ready!==true)issues.push(...(post.readiness?.issues?.length?post.readiness.issues:['Проверьте текст и файлы материала.']));if(schedule&&!soonShiftPossible()&&!(Date.parse(post.scheduledAt)>Date.now()))issues.push('Выберите дату и время публикации в будущем.');if(!post.platformIds.length)issues.push('Выберите площадки.');const unavailable=post.platformIds.filter(id=>!context?.channels?.some(c=>c.id===id&&c.connected===true&&c.enabled===true));if(schedule&&unavailable.length)issues.push('Не готовы к отправке: '+unavailable.map(name).join(', ')+'. Подключите площадки и включите отправку.');if(post.platformIds.includes('tiktok')&&!post.platformOptions?.tiktok?.privacy)issues.push('Выберите, кто увидит видео TikTok в форме изменения материала.');if(post.planLink&&post.platformIds.some(id=>id!==post.planLink.platform))issues.push('Площадка должна совпадать с согласованным контент-планом.');return issues;}
// 02.11.2026: прошедшее или не указанное время сдвигается на ближайшее допустимое (через 2 минуты) прямо перед согласованием.
const SOON_MS=2*60*1000;
function soonShiftPossible(){return typeof options.updatePost==='function';}
function needsSoonShift(){return !(Date.parse(post.scheduledAt)>Date.now()+SOON_MS);}

let shiftedSoon=null;
try{if(action==='approve'&&payload.schedule===true&&needsSoonShift()){if(!soonShiftPossible())throw Object.assign(Error('Выберите дату и время публикации в будущем.'),{definitive:true});const soon=new Date(Math.ceil((Date.now()+SOON_MS)/60000)*60000).toISOString();const moved=checkedMaterial(await options.updatePost(id,{revision:post.revision,scheduledAt:soon,...(post.timezone?{timezone:post.timezone}:{})},{signal:own.signal}),id);if(moved.revision<=post.revision||moved.scheduledAt!==soon)throw Object.assign(Error('Новое время не подтверждено.'),{unknown:true});post=moved;payload={...payload,revision:moved.revision};shiftedSoon=soon;}
 let result=checkedMaterial(await actionTransport(action,payload,own.signal),id);if(action==='approve'&&payload.approved===false&&result.status!=='draft'){if(!['failed','cancelled','needs_review'].includes(result.status)||typeof options.updatePost!=='function')throw Object.assign(Error('Согласование снято. Откройте редактирование, чтобы вернуть материал в черновик.'),{definitive:true});post=result;result=checkedMaterial(await options.updatePost(id,{revision:result.revision,scheduledAt:result.scheduledAt??null},{signal:own.signal}),id);}if(result.revision<=payload.revision||action==='approve'&&payload.schedule===true&&(!['scheduled','publishing','published'].includes(result.status)||result.approval?.approved!==true)||action==='approve'&&payload.approved===true&&result.approval?.approved!==true||action==='approve'&&payload.approved===false&&(result.approval?.approved===true||result.status!=='draft'))throw Object.assign(Error('Результат действия не подтверждён новой версией и статусом.'),{unknown:true});if(disposed)return;post=result;state.textContent=action==='approve'&&payload.schedule===true?(shiftedSoon?'Согласовано. Материал уйдёт как можно скорее: '+dateLabel(shiftedSoon,post.timezone)+'.':'Согласовано. Материал поставлен на публикацию в указанное время.'):action==='approve'&&payload.approved===false?'Черновик сохранён. Ещё не начатая отправка остановлена.':action==='approve'&&payload.approved===true?'Согласовано без отправки.':action==='schedule'?(post.status==='scheduled'?'Отправка запланирована.':'Ответ получен. Проверьте фактический статус карточки.'):'Состояние карточки обновлено.';notify(post);}
